import { useId, type ReactNode, type CSSProperties } from 'react';
import './ApplicationShell.css';

export interface ShellState { section: string; inspectorWidth: number; mobilePane: 'navigation' | 'workspace' | 'inspector' }
export type ShellAction = { type: 'navigate'; section: string } | { type: 'resize-inspector'; width: number } | { type: 'show-pane'; pane: ShellState['mobilePane'] };
export function ApplicationShell({ state, dispatch, workspace, inspector }: { state: ShellState; dispatch: (action: ShellAction) => void; workspace: ReactNode; inspector: ReactNode }) {
  const id = useId();
  const width = Math.min(440, Math.max(240, state.inspectorWidth));
  const sections = [{ title: 'Workspace', items: ['Overview', 'Projects'] }, { title: 'Organization', items: ['People', 'Settings'] }];
  return <div className="app-shell" data-pane={state.mobilePane} style={{ '--inspector-width': width + 'px' } as CSSProperties}>
    <a className="skip-link" href={'#' + id + '-workspace'}>Skip to workspace</a>
    <header className="shell-toolbar"><strong>Workspace</strong><div className="mobile-panes" aria-label="Visible pane">{(['navigation', 'workspace', 'inspector'] as const).map(pane => <button key={pane} type="button" aria-pressed={state.mobilePane === pane} onClick={() => dispatch({ type: 'show-pane', pane })}>{pane}</button>)}</div></header>
    <nav className="shell-nav" aria-label="Primary navigation" tabIndex={0}>{sections.map(section => <section key={section.title}><h2>{section.title}</h2>{section.items.map(item => <button key={item} aria-current={state.section === item ? 'page' : undefined} onClick={() => { dispatch({ type: 'navigate', section: item }); dispatch({ type: 'show-pane', pane: 'workspace' }); }}>{item}</button>)}</section>)}</nav>
    <main id={id + '-workspace'} className="shell-workspace" tabIndex={0}>{workspace}</main>
    <aside className="shell-inspector" aria-label="Inspector" tabIndex={0}><label className="inspector-size">Inspector width<input aria-label="Inspector width" type="range" min={240} max={440} step={8} value={width} onChange={event => dispatch({ type: 'resize-inspector', width: Number(event.target.value) })}/></label>{inspector}</aside>
  </div>;
}

