* { box-sizing: border-box; }
.app-shell { height: 100dvh; display: grid; grid-template: auto minmax(0, 1fr) / 14rem minmax(0, 1fr) var(--inspector-width); overflow: hidden; color: #20232a; background: #fff; }
.shell-toolbar { grid-column: 1 / -1; padding: .75rem 1rem; border-bottom: 1px solid #c5c9d0; }
.shell-nav, .shell-workspace, .shell-inspector { min-width: 0; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 1rem; overflow-wrap: anywhere; }
.shell-nav { border-right: 1px solid #c5c9d0; }
.shell-nav h2 { font-size: .8rem; }
.shell-nav button { display: block; width: 100%; padding: .65rem; text-align: left; }
.shell-nav [aria-current] { font-weight: bold; text-decoration: underline; }
.shell-inspector { border-left: 1px solid #c5c9d0; }
.inspector-size { display: grid; gap: .5rem; margin-bottom: 1rem; }
button, input { font: inherit; }
:focus-visible { outline: 3px solid #205ed8; outline-offset: 2px; }
.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 10; background: white; padding: 1rem; }
.skip-link:focus { top: .5rem; }
.mobile-panes { display: none; }
@media (max-width: 800px) { .app-shell { grid-template-columns: minmax(0, 1fr); } .mobile-panes { display: flex; flex-wrap: wrap; gap: .5rem; margin-top: .5rem; } .shell-nav, .shell-workspace, .shell-inspector { grid-column: 1; grid-row: 2; display: none; border: 0; } .app-shell[data-pane="navigation"] .shell-nav, .app-shell[data-pane="workspace"] .shell-workspace, .app-shell[data-pane="inspector"] .shell-inspector { display: block; } .inspector-size { display: none; } }
